/// A port refused a message because its target's mailbox is full. The caller
/// keeps the message; nothing was changed or lost.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Rejected;

/// What one call of `System::step_once` did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Progress {
    /// One message was delivered.
    Delivered,
    /// No mailbox holds a message.
    Settled,
    /// Messages are pending, but every delivery is blocked by a full mailbox or
    /// by an outbox the environment has not emptied.
    Blocked,
}

/// `System::run` stopped before the system settled.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stopped {
    /// The step budget ran out before the system settled.
    Budget {
        /// Deliveries performed.
        steps: usize,
    },
    /// Messages are pending but every delivery is blocked.
    Blocked {
        /// Deliveries performed before blocking.
        steps: usize,
    },
}

enum Attempt {
    Delivered,
    Blocked,
    Idle,
}

